import {normalizedPrompts,maskToPaths,insidePath} from './segment-model.js?v=20261025-tch1';
import {segmentTap} from './segment-tap.js?v=20261025-tch1';
import {PAPERS} from './vision.js?v=20261025-tch1';
// AI Trace: a tap outside every tool traces a new one; a tap inside an AI-traced tool selects it. The ＋ and − buttons
// in the canvas toolbar arm one tap that adds a missed part to, or removes an area from, the selected tool.
// `?segdebug` overlays what the model returned, the window it zoomed into and the taps it was given.
const ENGINE='mediapipe',svg=d=>`<svg class="ui-icon" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.3" stroke-linecap="round" aria-hidden="true"><circle cx="8" cy="8" r="5.5"/><path d="${d}"/></svg>`;
export function createTapUI(api){const $=id=>document.getElementById(id),debug=new URLSearchParams(location.search).has('segdebug');let seen=null,armed=null,serial=0,working=false,module=null,message='',failed=false,loaded=false;
 const buttons=document.createElement('div');buttons.className='tap-tools';buttons.hidden=true;buttons.innerHTML=`<span></span><button id="tapAdd" aria-pressed="false" title="Add a missed part: tap it next" aria-label="Add a missed part to the selected tool">${svg('M8 5.5v5M5.5 8h5')}</button><button id="tapRemove" aria-pressed="false" title="Remove an area: tap it next" aria-label="Remove an area from the selected tool">${svg('M5.5 8h5')}</button>`;
 $('undoBtn').previousElementSibling.before(buttons);
 const work=document.createElement('div');work.id='tapWork';work.hidden=true;work.innerHTML='<progress id="tapProgress" aria-label="Model download"></progress><span id="tapStatus" role="status" aria-live="polite"></span><button id="tapCancel">Cancel</button><button id="tapRetry" hidden>Retry</button><button id="tapFallback" hidden>Smart edges</button>';
 $('canvasArea').append(work);
 function status(text,error=false){message=text;failed=error;update();}
 function update(){const s=api.state(),active=s.traceMethod==='tap',tool=s.tools[s.selected];buttons.hidden=!active;for(const [id,m] of [['tapAdd','add'],['tapRemove','remove']]){$(id).setAttribute('aria-pressed',String(armed===m));$(id).disabled=working||!tool?.tap;}
  const hint=!message&&!working&&active&&api.photo()?(armed==='add'?'Tap the part the outline missed':armed==='remove'?'Tap the area to remove':s.tools.length?'':'Tap a tool to trace it'):'';
  work.hidden=!active||!(working||message||hint);work.classList.toggle('error',failed);$('tapStatus').textContent=message||hint;$('tapProgress').hidden=!working;$('tapCancel').hidden=!working;$('tapRetry').hidden=$('tapFallback').hidden=!failed||loaded;}
 function progress(p){if(p.phase==='download'){message=`Downloading AI model${p.loaded?` · ${(p.loaded/1e6).toFixed(1)}${p.total?' / '+(p.total/1e6).toFixed(1):''} MB`:''}`;if(p.total){$('tapProgress').max=p.total;$('tapProgress').value=p.loaded||0;}else $('tapProgress').removeAttribute('value');}else{message={runtime:'Loading AI model…',initializing:'Preparing AI model…',embedding:'Reading photo…'}[p.phase]||'Tracing…';$('tapProgress').removeAttribute('value');}update();}
 async function ready(expected=serial){module||=await import('./segment.js?v=20261025-tch1');if(expected!==serial)throw new DOMException('Cancelled','AbortError');const model=await module.loadSegmenter(ENGINE,progress);loaded=true;return model;}
 function invalidate(){const cancel=working;seen=null;serial++;working=false;armed=null;message='';failed=false;if(cancel){module?.cancelSegmenter(ENGINE);loaded=false;}update();}
 async function activate(){if(api.state().traceMethod!=='tap'){invalidate();return;}api.overlay();update();if(!api.photo())return status('Choose the original photo to trace.');const job=++serial;working=true;status('Loading AI model…');try{await ready();if(job===serial)status('');}catch(e){if(job===serial&&e.name!=='AbortError')status(e.message,true);}finally{if(job===serial){working=false;update();}}}
 async function run(points,index){if(working)return;if(index<0&&api.state().tools.length>=50)return api.toast('A Trace project can contain up to 50 tools.');const rect=api.photo();if(!rect)return status('Choose the original photo to trace.');if(points.length>64)return api.toast('Use up to 64 taps per tool.');try{normalizedPrompts(points,rect);}catch(e){return api.toast(e.message);}const before=api.snapshot(),job=++serial;working=true;status('Tracing…');
  try{const segmenter=await ready(),result=await segmentTap(segmenter,rect,points),paths=maskToPaths(result,rect,api.state().paper,{minArea:api.state().minToolArea,points:result.prompts||points});seen=result.view?{...result.view,rect,url:null}:null;if(job!==serial||api.photo()!==rect||api.snapshot()!==before)return;if(!paths.length)throw Error('No complete tool found. Tap farther inside the tool.');{const xs=paths[0].map(p=>p[0]),ys=paths[0].map(p=>p[1]),[w,h]=PAPERS[api.state().paper]||PAPERS.a4;if(Math.max(...xs)-Math.min(...xs)>w*.9&&Math.max(...ys)-Math.min(...ys)>h*.9)throw Error('That traced the sheet, not a tool. Tap on the tool itself.');}const s=api.state();api.remember();const tool={...(s.tools[index]||{name:`Tool ${s.tools.length+1}`}),points:paths[0],tap:{engine:ENGINE,points:result.prompts||points}};if(index<0){s.tools.push(tool);s.selected=s.tools.length-1;}else{s.tools[index]=tool;s.selected=index;}api.commit();
   if(job===serial){failed=false;message='';api.draw();if(index<0)api.traced?.();}
  }catch(e){if(job===serial&&e.name!=='AbortError')status(e.message,true);}finally{if(job===serial){working=false;update();}}
 }
 async function tap(p){if(working)return api.toast('Wait for tracing, or cancel.');const s=api.state(),mode=armed;armed=null;
  // Inside an AI-traced tool a tap selects it; inside one traced another way it retraces it with AI.
  if(!mode){const hit=s.tools.findIndex(t=>insidePath(p,t.points));if(hit>=0&&s.tools[hit].tap){s.selected=hit;api.draw();update();return;}return run([{...p,label:1}],hit);}
  const tool=s.tools[s.selected];if(!tool?.tap){update();return api.toast('Select an AI-traced tool first.');}await run([...tool.tap.points,{...p,label:mode==='add'?1:0}],s.selected);}
 $('tapAdd').onclick=()=>{armed=armed==='add'?null:'add';update();};$('tapRemove').onclick=()=>{armed=armed==='remove'?null:'remove';update();};
 $('tapCancel').onclick=()=>{invalidate();status('Cancelled',true);};$('tapRetry').onclick=activate;$('tapFallback').onclick=()=>api.method('edges');
 function draw(add){if(api.state().traceMethod!=='tap')return;const radius=4/Math.max(.01,Math.abs($('editor').getScreenCTM()?.a||1));
  if(debug&&seen&&seen.rect===api.photo()){const r=seen.rect,s=r.scale,[ox,oy]=r.origin||[0,0],[wx,wy,ww,wh]=seen.window;if(!seen.url){const c=document.createElement('canvas');c.width=seen.width;c.height=seen.height;const ctx=c.getContext('2d'),img=ctx.createImageData(c.width,c.height);for(let i=0;i<seen.mask.length;i++)if(seen.mask[i]){img.data[i*4]=255;img.data[i*4+1]=96;img.data[i*4+2]=24;img.data[i*4+3]=120;}ctx.putImageData(img,0,0);seen.url=c.toDataURL();}
   add('tap-seen','image',{href:seen.url,x:wx/s+ox,y:wy/s+oy,width:ww/s,height:wh/s,preserveAspectRatio:'none','pointer-events':'none',class:'tap-seen'});add('tap-window','rect',{x:wx/s+ox,y:wy/s+oy,width:ww/s,height:wh/s,class:'tap-window','pointer-events':'none'});
   for(const [i,[x,y,label]] of seen.taps.entries())add('tap-auto-'+i,'circle',{cx:x/s+ox,cy:y/s+oy,r:radius*.8,class:label?'tap-auto':'tap-negative','pointer-events':'none'});}
  const tool=api.state().tools[api.state().selected];for(const [i,p] of (tool?.tap?.points||[]).entries())add('tap-point-'+i,'circle',{cx:p.x,cy:p.y,r:radius,class:p.label?'tap-positive':'tap-negative','pointer-events':'none'});}
 return {tap,activate,invalidate,update,draw,get active(){return api.state().traceMethod==='tap';}};
}
